import json
import math
import sqlite3
from typing import Any, Dict, List, Optional, Tuple

# ---- Milvus ----
from pymilvus import connections, Collection, utility

# ---- Embedding model ----
from sentence_transformers import SentenceTransformer


# =========================
# Fixed configuration (per requirement)
# =========================
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

MILVUS_CONFIG = {
    "milvus_collections": {
        "reviews": "reviews",
        "photos": "photo_vector",
        "tips": "milvus_tip"
    },
    "milvus_host": "localhost",
    "milvus_port": "19530"
}


# =========================
# Helpers
# =========================
def connect_sqlite(path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    return conn


def table_exists(conn: sqlite3.Connection, table: str) -> bool:
    cur = conn.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (table,))
    return cur.fetchone() is not None


def list_tables(conn: sqlite3.Connection) -> List[str]:
    cur = conn.execute("SELECT name FROM sqlite_master WHERE type='table'")
    return [r[0] for r in cur.fetchall()]


def get_columns(conn: sqlite3.Connection, table: str) -> List[str]:
    cur = conn.execute(f"PRAGMA table_info({table})")
    return [r[1] for r in cur.fetchall()]


def safe_json_loads(x: Any) -> Any:
    if x is None:
        return None
    if isinstance(x, (dict, list)):
        return x
    if not isinstance(x, str):
        return None
    x = x.strip()
    if not x:
        return None
    try:
        return json.loads(x)
    except Exception:
        return None


def parse_hours(hours_val: Any) -> Dict[str, str]:
    """Return dict like {'Monday': '00:00-24:00', ...} if possible."""
    h = safe_json_loads(hours_val)
    if isinstance(h, dict):
        return {str(k): str(v) for k, v in h.items()}
    # Sometimes stored as plain text; do best-effort
    if isinstance(hours_val, str) and ('-' in hours_val and ':' in hours_val):
        # Cannot reliably parse; return empty and let downstream handle heuristics
        return {}
    return {}


def is_24h(hours_dict: Dict[str, str]) -> bool:
    """Heuristic: if any day explicitly shows 24h range, or many days."""
    if not hours_dict:
        return False
    patterns = {
        "00:00-24:00", "0:00-24:00",
        "00:00-23:59", "0:00-23:59",
        "00:00-00:00", "0:00-0:00"  # some datasets use 00:00-00:00 to mean 24h
    }
    hit_days = 0
    for _, v in hours_dict.items():
        v2 = v.replace(' ', '')
        if v2 in patterns:
            hit_days += 1
        # also allow multiple ranges that cover whole day (rare)
        if v2.startswith('00:00-') and v2.endswith('24:00'):
            hit_days += 1
    return hit_days >= 1


def categories_match(categories: Optional[str]) -> bool:
    if not categories:
        return False
    c = categories.lower()
    keywords = [
        'coffee', 'cafe', 'cafes', 'tea', 'bubble tea',
        'library', 'bookstore', 'baker', 'bakery',
        'diner', 'donuts', 'dessert', 'sandwiches'
    ]
    return any(k in c for k in keywords)


def attributes_study_score(attrs_val: Any) -> float:
    """Heuristic score from attributes JSON (if present)."""
    attrs = safe_json_loads(attrs_val)
    if not isinstance(attrs, dict):
        return 0.0

    score = 0.0

    # WiFi
    wifi = attrs.get('WiFi') or attrs.get('wifi')
    if isinstance(wifi, str):
        w = wifi.strip().lower()
        if 'free' in w:
            score += 1.0
        elif 'paid' in w:
            score += 0.5

    # Good for working
    gfw = attrs.get('GoodForWorking') or attrs.get('good_for_working')
    if isinstance(gfw, (bool, int)) and bool(gfw):
        score += 1.5

    # Noise level
    nl = attrs.get('NoiseLevel') or attrs.get('noise_level')
    if isinstance(nl, str):
        n = nl.strip().lower()
        if 'quiet' in n:
            score += 1.0
        elif 'average' in n:
            score += 0.3

    # RestaurantsGoodForGroups can be negative for studying, but keep neutral

    return score


def base_quality_score(stars: Any, review_count: Any) -> float:
    try:
        s = float(stars)
    except Exception:
        s = 0.0
    try:
        rc = int(review_count)
    except Exception:
        rc = 0
    return s + 0.2 * math.log1p(rc)


# =========================
# Step 1: Fetch candidate businesses (SQLite)
# =========================
def fetch_candidate_businesses(city: Optional[str] = None, state: Optional[str] = None, limit_sql: int = 5000) -> List[Dict[str, Any]]:
    conn = connect_sqlite(sqlite_paths['business'])
    try:
        # find business table
        biz_table = 'business' if table_exists(conn, 'business') else None
        if biz_table is None:
            # fallback: find a table that has business_id and name
            for t in list_tables(conn):
                cols = set(get_columns(conn, t))
                if 'business_id' in cols and 'name' in cols:
                    biz_table = t
                    break
        if biz_table is None:
            raise RuntimeError(f"Cannot locate business table in {sqlite_paths['business']}. Tables={list_tables(conn)}")

        cols = set(get_columns(conn, biz_table))
        select_cols = [c for c in [
            'business_id','name','address','city','state','postal_code','latitude','longitude',
            'stars','review_count','categories','attributes','hours','is_open'
        ] if c in cols]
        if 'business_id' not in cols or 'name' not in cols:
            raise RuntimeError(f"Business table {biz_table} missing required columns. Columns={sorted(cols)}")

        where = []
        params: List[Any] = []
        if city and 'city' in cols:
            where.append('city = ?')
            params.append(city)
        if state and 'state' in cols:
            where.append('state = ?')
            params.append(state)
        if 'is_open' in cols:
            where.append('is_open = 1')

        sql = f"SELECT {', '.join(select_cols)} FROM {biz_table}"
        if where:
            sql += ' WHERE ' + ' AND '.join(where)
        sql += f' LIMIT {int(limit_sql)}'

        rows = conn.execute(sql, params).fetchall()

        candidates: List[Dict[str, Any]] = []
        for r in rows:
            d = dict(r)
            hours_dict = parse_hours(d.get('hours'))
            if not is_24h(hours_dict):
                continue

            cat_ok = categories_match(d.get('categories'))
            attr_score = attributes_study_score(d.get('attributes'))
            if not (cat_ok or attr_score > 0):
                # require some evidence of study-friendliness
                continue

            d['_hours_dict'] = hours_dict
            d['_attr_score'] = attr_score
            d['_base_score'] = base_quality_score(d.get('stars'), d.get('review_count'))
            candidates.append(d)

        # keep top by base + attr
        candidates.sort(key=lambda x: (x.get('_base_score', 0.0) + x.get('_attr_score', 0.0)), reverse=True)
        return candidates[:300]
    finally:
        conn.close()


# =========================
# Step 2: Vector search in Milvus (reviews + tips)
# =========================
def milvus_connect() -> None:
    connections.connect(
        alias='default',
        host=MILVUS_CONFIG['milvus_host'],
        port=MILVUS_CONFIG['milvus_port']
    )


def collection_available(name: str) -> bool:
    try:
        return utility.has_collection(name)
    except Exception:
        return False


def milvus_search_study_relevance(
    business_ids: List[str],
    query_text: str,
    topk: int = 80
) -> Dict[str, List[Dict[str, Any]]]:
    """Return hits grouped by business_id.

    Output structure: {business_id: [{'source':'reviews'/'tips', 'id':..., 'score':...}, ...]}

    Notes:
    - This tries to use expr filtering by business_id if field exists.
    - If schema differs, it falls back to unfiltered search then filters client-side.
    """
    milvus_connect()

    model = SentenceTransformer('sentence-transformers/all-MiniLM-L6-v2')
    qvec = model.encode([query_text], normalize_embeddings=True).tolist()

    grouped: Dict[str, List[Dict[str, Any]]] = {bid: [] for bid in business_ids}

    def run_one(collection_name: str, source: str) -> None:
        if not collection_available(collection_name):
            return
        col = Collection(collection_name)
        col.load()

        # Attempt to infer vector field name
        schema_fields = [f.name for f in col.schema.fields]
        vec_field = None
        for cand in ['embedding', 'vector', 'text_vector', 'review_vector', 'tip_vector']:
            if cand in schema_fields:
                vec_field = cand
                break
        if vec_field is None:
            # fallback: pick first FLOAT_VECTOR
            for f in col.schema.fields:
                if str(f.dtype).endswith('FLOAT_VECTOR'):
                    vec_field = f.name
                    break
        if vec_field is None:
            raise RuntimeError(f"Cannot find vector field in Milvus collection {collection_name}. Fields={schema_fields}")

        # Identify likely id fields
        id_field = None
        for cand in ['review_id','tip_id','id','pk']:
            if cand in schema_fields:
                id_field = cand
                break

        biz_field = 'business_id' if 'business_id' in schema_fields else None

        output_fields = [f for f in [biz_field, id_field] if f]

        # Try server-side filter
        expr = None
        if biz_field and business_ids:
            # Milvus expr length can be limited; keep it manageable
            # If too many business_ids, skip expr and filter client-side
            if len(business_ids) <= 200:
                quoted = ','.join([f"\"{b}\"" for b in business_ids])
                expr = f"{biz_field} in [{quoted}]"

        # Execute search
        try:
            res = col.search(
                data=qvec,
                anns_field=vec_field,
                param={'metric_type': 'IP', 'params': {'nprobe': 16}},
                limit=topk,
                expr=expr,
                output_fields=output_fields
            )
        except Exception:
            # fallback without expr and/or different metric
            res = col.search(
                data=qvec,
                anns_field=vec_field,
                param={'metric_type': 'L2', 'params': {'nprobe': 16}},
                limit=topk,
                output_fields=output_fields
            )

        # res is a list (per query); we only have one query
        hits = res[0]
        for h in hits:
            ent = getattr(h, 'entity', None)
            if ent is None:
                continue
            bid = ent.get(biz_field) if biz_field else None
            if bid is None:
                continue
            if business_ids and bid not in grouped:
                continue
            hid = ent.get(id_field) if id_field else None
            grouped.setdefault(bid, []).append({
                'source': source,
                'id': hid,
                'score': float(h.score)
            })

    run_one(MILVUS_CONFIG['milvus_collections']['reviews'], 'reviews')
    run_one(MILVUS_CONFIG['milvus_collections']['tips'], 'tips')

    # Keep top few per business
    for bid, arr in grouped.items():
        arr.sort(key=lambda x: x['score'], reverse=True)
        grouped[bid] = arr[:6]

    return grouped


# =========================
# Step 3: Fetch snippets from SQLite review/tip
# =========================
def fetch_review_texts(review_ids: List[str]) -> Dict[str, Dict[str, Any]]:
    if not review_ids:
        return {}
    conn = connect_sqlite(sqlite_paths['review'])
    try:
        table = 'review' if table_exists(conn, 'review') else None
        if table is None:
            for t in list_tables(conn):
                cols = set(get_columns(conn, t))
                if 'review_id' in cols and 'text' in cols:
                    table = t
                    break
        if table is None:
            return {}

        cols = set(get_columns(conn, table))
        wanted = [c for c in ['review_id','business_id','text','date','stars'] if c in cols]
        qmarks = ','.join(['?'] * len(review_ids))
        sql = f"SELECT {', '.join(wanted)} FROM {table} WHERE review_id IN ({qmarks})"
        rows = conn.execute(sql, review_ids).fetchall()
        return {r['review_id']: dict(r) for r in rows}
    finally:
        conn.close()


def fetch_tip_texts(tip_ids: List[str]) -> Dict[str, Dict[str, Any]]:
    if not tip_ids:
        return {}
    conn = connect_sqlite(sqlite_paths['tip'])
    try:
        table = 'tip' if table_exists(conn, 'tip') else None
        if table is None:
            for t in list_tables(conn):
                cols = set(get_columns(conn, t))
                if 'text' in cols and ('user_id' in cols or 'business_id' in cols):
                    table = t
                    break
        if table is None:
            return {}

        cols = set(get_columns(conn, table))
        # Yelp tip table often doesn't have tip_id; may use (user_id,business_id,date)
        if 'tip_id' not in cols:
            # If no tip_id, we cannot reliably fetch by id; return empty
            return {}

        wanted = [c for c in ['tip_id','business_id','text','date','compliment_count'] if c in cols]
        qmarks = ','.join(['?'] * len(tip_ids))
        sql = f"SELECT {', '.join(wanted)} FROM {table} WHERE tip_id IN ({qmarks})"
        rows = conn.execute(sql, tip_ids).fetchall()
        return {r['tip_id']: dict(r) for r in rows}
    finally:
        conn.close()


# =========================
# Step 4: Rank and present
# =========================
def rank_businesses(
    candidates: List[Dict[str, Any]],
    hits_by_biz: Dict[str, List[Dict[str, Any]]],
    review_text_by_id: Dict[str, Dict[str, Any]],
    tip_text_by_id: Dict[str, Dict[str, Any]],
    topn: int = 10
) -> List[Dict[str, Any]]:
    out = []
    for b in candidates:
        bid = b.get('business_id')
        hits = hits_by_biz.get(bid, [])

        # Vector relevance score: take max score among hits (after normalization assumption)
        # If using IP with normalized embeddings, score in [-1,1]; otherwise arbitrary.
        vec_score = max([h['score'] for h in hits], default=0.0)

        # Combine
        final = float(b.get('_base_score', 0.0)) + float(b.get('_attr_score', 0.0)) + 1.5 * vec_score

        # Build snippets
        snippets: List[str] = []
        for h in hits[:3]:
            if h['source'] == 'reviews' and h['id'] in review_text_by_id:
                txt = review_text_by_id[h['id']].get('text', '')
                snippets.append(f"[review] {txt[:220].replace('
',' ')}")
            elif h['source'] == 'tips' and h['id'] in tip_text_by_id:
                txt = tip_text_by_id[h['id']].get('text', '')
                snippets.append(f"[tip] {txt[:220].replace('
',' ')}")

        out.append({
            'business_id': bid,
            'name': b.get('name'),
            'address': b.get('address'),
            'city': b.get('city'),
            'state': b.get('state'),
            'postal_code': b.get('postal_code'),
            'stars': b.get('stars'),
            'review_count': b.get('review_count'),
            'categories': b.get('categories'),
            'hours': b.get('_hours_dict', {}),
            'study_attr_score': b.get('_attr_score', 0.0),
            'vector_relevance': vec_score,
            'final_score': final,
            'snippets': snippets
        })

    out.sort(key=lambda x: x['final_score'], reverse=True)
    return out[:topn]


def main():
    # Optional: set city/state to narrow results
    CITY = None   # e.g. 'Las Vegas'
    STATE = None  # e.g. 'NV'

    query_text = 'late night studying quiet wifi outlets open 24 hours good for working'

    # Step 1
    candidates = fetch_candidate_businesses(city=CITY, state=STATE)
    if not candidates:
        print('No candidate 24-hour + study-friendly places found with current filters. Try setting CITY/STATE or relaxing heuristics.')
        return

    business_ids = [c['business_id'] for c in candidates if c.get('business_id')]

    # Step 2
    try:
        hits_by_biz = milvus_search_study_relevance(business_ids, query_text=query_text, topk=120)
    except Exception as e:
        print(f"[WARN] Milvus search failed, will rank using only structured signals. Error: {e}")
        hits_by_biz = {bid: [] for bid in business_ids}

    # Step 3: gather ids
    review_ids = []
    tip_ids = []
    for bid, hits in hits_by_biz.items():
        for h in hits:
            if h['source'] == 'reviews' and h.get('id'):
                review_ids.append(h['id'])
            if h['source'] == 'tips' and h.get('id'):
                tip_ids.append(h['id'])
    review_ids = list(dict.fromkeys(review_ids))
    tip_ids = list(dict.fromkeys(tip_ids))

    review_text_by_id = fetch_review_texts(review_ids)
    tip_text_by_id = fetch_tip_texts(tip_ids)

    # Step 4
    ranked = rank_businesses(candidates, hits_by_biz, review_text_by_id, tip_text_by_id, topn=10)

    # Output
    for i, r in enumerate(ranked, 1):
        loc = ', '.join([x for x in [r.get('address'), r.get('city'), r.get('state'), r.get('postal_code')] if x])
        print(f"
#{i} {r['name']}")
        print(f"  Location: {loc}")
        print(f"  Rating: {r.get('stars')} ({r.get('review_count')} reviews)")
        print(f"  Categories: {r.get('categories')}")
        print(f"  24h Hours (parsed): {r.get('hours')}")
        print(f"  Scores -> final={r['final_score']:.3f}, vector={r['vector_relevance']:.3f}, attr={r['study_attr_score']:.3f}")
        if r['snippets']:
            print('  Evidence:')
            for s in r['snippets']:
                print(f"   - {s}")


if __name__ == '__main__':
    main()

