import json
import sqlite3
from collections import defaultdict

from pymilvus import connections, Collection
from sentence_transformers import SentenceTransformer


# ---------------------------
# Fixed configuration (as required)
# ---------------------------
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

config = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530',
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}


def safe_json_loads(val):
    """Yelp business.attributes often stored as JSON-like string; be defensive."""
    if val is None:
        return {}
    if isinstance(val, dict):
        return val
    if not isinstance(val, str):
        return {}
    val = val.strip()
    if not val:
        return {}

    # Try strict JSON
    try:
        return json.loads(val)
    except Exception:
        pass

    # Some dumps may use single quotes / Python literals; attempt a mild normalization
    try:
        normalized = val.replace("'", '"')
        return json.loads(normalized)
    except Exception:
        return {}


def get_attr(attributes: dict, key: str, default=None):
    return attributes.get(key, default) if isinstance(attributes, dict) else default


def parse_bool(v):
    if isinstance(v, bool):
        return v
    if isinstance(v, str):
        return v.lower() in ("true", "1", "yes")
    if isinstance(v, (int, float)):
        return v != 0
    return False


def attribute_score(attrs: dict) -> float:
    """Heuristic scoring for romantic/quiet/private vibe."""
    score = 0.0

    ambience = get_attr(attrs, "Ambience", {})
    if isinstance(ambience, str):
        # sometimes nested dict is stored as a JSON string
        ambience = safe_json_loads(ambience)

    romantic = False
    if isinstance(ambience, dict):
        romantic = parse_bool(ambience.get("romantic"))
    if romantic:
        score += 3.0

    noise = get_attr(attrs, "NoiseLevel")
    if isinstance(noise, str):
        n = noise.strip().lower()
        if "quiet" in n:
            score += 2.5
        elif "average" in n:
            score += 1.0

    private_room = parse_bool(get_attr(attrs, "RestaurantsPrivateRoom"))
    if private_room:
        score += 2.5

    reservations = parse_bool(get_attr(attrs, "RestaurantsReservations"))
    if reservations:
        score += 1.0

    good_for_meal = get_attr(attrs, "GoodForMeal", {})
    if isinstance(good_for_meal, str):
        good_for_meal = safe_json_loads(good_for_meal)
    if isinstance(good_for_meal, dict) and parse_bool(good_for_meal.get("dinner")):
        score += 1.0

    has_tv = get_attr(attrs, "HasTV")
    if isinstance(has_tv, str) or isinstance(has_tv, bool):
        if not parse_bool(has_tv):
            score += 0.5

    return score


def milvus_semantic_business_candidates(query_text: str, topk: int = 50):
    """Search Milvus reviews and tips; return business_id -> best similarity score per source."""
    # Embedding model
    model = SentenceTransformer('sentence-transformers/all-MiniLM-L6-v2')
    qvec = model.encode([query_text], normalize_embeddings=True)[0].tolist()

    connections.connect(alias="default", host=config['milvus_host'], port=config['milvus_port'])

    def search_collection(collection_name: str, output_fields=None):
        col = Collection(collection_name)
        col.load()
        # NOTE: field name for vector may differ in your schema.
        # Common choices: 'embedding', 'vector', 'text_vector'. Adjust if needed.
        vector_field_candidates = ['embedding', 'vector', 'text_vector', 'emb']
        vec_field = None
        for c in vector_field_candidates:
            if c in [f.name for f in col.schema.fields]:
                vec_field = c
                break
        if vec_field is None:
            raise RuntimeError(f"Cannot find vector field in Milvus collection {collection_name}. Tried {vector_field_candidates}.")

        if output_fields is None:
            output_fields = ['business_id']

        res = col.search(
            data=[qvec],
            anns_field=vec_field,
            param={"metric_type": "IP", "params": {"nprobe": 16}},
            limit=topk,
            output_fields=output_fields
        )
        return res

    business_best = defaultdict(lambda: {"review_score": None, "tip_score": None})

    # Reviews
    try:
        review_res = search_collection(config['milvus_collections']['reviews'], output_fields=['business_id'])
        for hit in review_res[0]:
            bid = hit.entity.get('business_id') if hasattr(hit, 'entity') else None
            if bid is None:
                continue
            score = float(hit.score)
            cur = business_best[bid]["review_score"]
            if cur is None or score > cur:
                business_best[bid]["review_score"] = score
    except Exception as e:
        print(f"[WARN] Review vector search failed: {e}")

    # Tips
    try:
        tip_res = search_collection(config['milvus_collections']['tips'], output_fields=['business_id'])
        for hit in tip_res[0]:
            bid = hit.entity.get('business_id') if hasattr(hit, 'entity') else None
            if bid is None:
                continue
            score = float(hit.score)
            cur = business_best[bid]["tip_score"]
            if cur is None or score > cur:
                business_best[bid]["tip_score"] = score
    except Exception as e:
        print(f"[WARN] Tip vector search failed: {e}")

    return business_best


def fetch_business_details(business_ids):
    if not business_ids:
        return []

    conn = sqlite3.connect(sqlite_paths['business'])
    conn.row_factory = sqlite3.Row

    # Adjust table/column names if your SQLite schema differs.
    # Yelp business commonly uses table name 'business'.
    placeholders = ",".join(["?"] * len(business_ids))
    sql = f"""
    SELECT
        business_id, name, address, city, state, postal_code,
        stars, review_count, categories, attributes, is_open
    FROM business
    WHERE business_id IN ({placeholders})
      AND is_open = 1
      AND categories LIKE '%Restaurants%'
    """

    rows = conn.execute(sql, list(business_ids)).fetchall()
    conn.close()
    return [dict(r) for r in rows]


def recommend_romantic_restaurants(query_text: str, topk_vector: int = 60, topn: int = 10):
    # 1) vector candidates
    cand_scores = milvus_semantic_business_candidates(query_text=query_text, topk=topk_vector)
    business_ids = list(cand_scores.keys())

    # 2) fetch details
    biz_rows = fetch_business_details(business_ids)

    # 3) rank
    results = []
    for b in biz_rows:
        bid = b['business_id']
        attrs = safe_json_loads(b.get('attributes'))

        # vector score: combine review/tip best scores
        rs = cand_scores[bid].get('review_score')
        ts = cand_scores[bid].get('tip_score')
        # If metric is IP on normalized vectors, score is roughly cosine similarity
        vscore = 0.0
        w = 0.0
        if rs is not None:
            vscore += 0.6 * rs
            w += 0.6
        if ts is not None:
            vscore += 0.4 * ts
            w += 0.4
        if w > 0:
            vscore = vscore / w

        ascore = attribute_score(attrs)

        # Overall score: mostly semantic, then attribute heuristics
        overall = 0.75 * vscore + 0.25 * (ascore / 10.0)  # normalize heuristic roughly

        # Collect matching reasons
        reasons = []
        ambience = get_attr(attrs, 'Ambience', {})
        if isinstance(ambience, str):
            ambience = safe_json_loads(ambience)
        if isinstance(ambience, dict) and parse_bool(ambience.get('romantic')):
            reasons.append('Ambience=romantic')
        noise = get_attr(attrs, 'NoiseLevel')
        if isinstance(noise, str) and 'quiet' in noise.lower():
            reasons.append('NoiseLevel=quiet')
        if parse_bool(get_attr(attrs, 'RestaurantsPrivateRoom')):
            reasons.append('PrivateRoom=True')
        if parse_bool(get_attr(attrs, 'RestaurantsReservations')):
            reasons.append('Reservations=True')

        results.append({
            'business_id': bid,
            'name': b.get('name'),
            'address': b.get('address'),
            'city': b.get('city'),
            'state': b.get('state'),
            'postal_code': b.get('postal_code'),
            'stars': b.get('stars'),
            'review_count': b.get('review_count'),
            'categories': b.get('categories'),
            'vector_score': vscore,
            'attribute_score': ascore,
            'overall_score': overall,
            'reasons': reasons
        })

    results.sort(key=lambda x: x['overall_score'], reverse=True)
    return results[:topn]


